import { TargetAndTransition, motion, useReducedMotion } from 'framer-motion';
import { isEmpty } from 'lodash-es';
import React, {
  AnimationEventHandler,
  forwardRef,
  useContext,
  useEffect,
  useRef,
} from 'react';
import styled from 'styled-components';

import AnimationsJS from '@dynatrace/strato-design-tokens/animations-js';
import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { PanelsContext } from './contexts/PanelsContext.js';
import { PanelsActions } from './types/panels-state.js';
import type {
  PanelSizes,
  PanelSize,
  DismissOptions,
} from './types/shared-panel-types.js';
import { useMergeRefs } from '../../../core/hooks/useMergeRefs.js';
import type { DataTestId } from '../../../core/types/data-props.js';
import type { StylingProps } from '../../../core/types/styling-props.js';
import type { WithChildren } from '../../../core/types/with-children.js';

/** @internal */
export interface PanelProps
  extends WithChildren,
    Omit<React.HTMLAttributes<HTMLDivElement>, 'onResize' | keyof StylingProps>,
    StylingProps,
    DataTestId {
  /** PanelName */
  name: string;
  /** The preferred width of the panel in px or %. */
  preferredWidth?: PanelSize;
  /** The minimum width the panel should have in pixels. */
  minWidth?: number;
  /** If the panel should be resizable. */
  resizable?: boolean;
  /**
   * If the panel should be dismissible.
   * @defaultValue 'left'
   */
  dismissible?: DismissOptions;
  /**
   * The order of the panels.
   * Needed for sorting the panels to ensure correct resizing behaviour.
   * If e.g. the page is not unmounted when navigating between routes, the 'main'
   * panel might be added before the 'sidebar' panel.
   * With the 'order' prop, we can still sort them correctly.
   */
  order: number;
  /**
   * Callback triggered after resizing is finished with the new panel sizes of
   * all existing panels and the newly applied panel width (in px).
   */
  onResize?: (sizes: PanelSizes, width: number) => void;
}

const StyledPanel = /* @__PURE__ */ styled(motion.div)({
  overflowY: 'auto',
  maxHeight: '100%',
  height: '100%',
  width: '100%',
  boxSizing: 'border-box',
  padding: Spacings.Size16,
  // Scrollable panels still need a tabIndex to be accessible for keyboard
  // scrolling. We do not need to show the default outline in this case though.
  '&:focus': {
    outline: 'none',
  },
});

/**
 * The `Panel` component adds a panel to the `ParentPanel`. The panel can be rendered
 * conditionally and can have a variety of configurations to e.g. give it a preferred width.
 * @internal
 */
export const Panel = forwardRef<HTMLDivElement, PanelProps>(
  (props, forwardedRef) => {
    const {
      name,
      preferredWidth,
      children,
      minWidth,
      resizable = true,
      dismissible: dismissibleProp = 'left',
      order,
      onResize,
      className: consumerClassName,
      style: consumerStyle,
      // Destructure animation callbacks from React.HTMLAttributes<HTMLDivElement>.
      // Those would conflict with the framer motion callbacks.
      // Should be fixed by the type once we have a concept for how to allow custom styles.
      onAnimationStart,
      onDrag,
      onDragEnd,
      onDragStart,
      'data-testid': dataTestId,
      ...remainingProps
    }: PanelProps = props;

    const panelRef = useRef<HTMLDivElement | null>(null);
    const rootRef = useMergeRefs([panelRef, forwardedRef]);
    const { disableAnimations, panelSizes, dispatch } =
      useContext(PanelsContext);
    const dismissible = dismissibleProp === true ? 'left' : dismissibleProp;

    const prefersReducedMotion = useReducedMotion();
    const animationProps: {
      [key: string]: TargetAndTransition | AnimationEventHandler;
    } = {
      initial: {
        position: 'absolute',
        ...(dismissible === 'left' ? { left: 0 } : { right: 0 }),
        opacity: 1,
      },
      animate: {
        position: 'relative',
        opacity: 1,
        transition: {
          delay: AnimationsJS.SlideIn.Duration.Fast,
        },
      },
      onAnimationStart: () => {
        // Adding the width to the animation would sometimes result in the content
        // flickering from full width to the final width when the animation is done.
        // Have to set it on the DOM node directly.
        // This is to make it appear like the opening panel is revealing the already
        // rendered content underneath, without the content reflowing.
        setTimeout(() => {
          panelRef.current &&
            (panelRef.current.style.width =
              panelSizes &&
              !isEmpty(panelSizes.current) &&
              panelSizes.current[name] !== undefined
                ? `${panelSizes.current[name].px}px`
                : '100%');
        });
      },
      onAnimationComplete: () => {
        panelRef.current && (panelRef.current.style.width = '100%');
        window.dispatchEvent(new Event('animationDone'));
      },
    };

    useEffect(() => {
      dispatch({
        type: PanelsActions.ADDPANEL,
        payload: {
          name,
          order,
          preferredWidth,
          minWidth,
          resizable,
          dismissible,
          onResize,
        },
      });

      return () => {
        dispatch({
          type: PanelsActions.REMOVEPANEL,
          payload: {
            name,
          },
        });
      };
      // only for mount and unmount
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    useEffect(() => {
      dispatch({
        type: PanelsActions.UPDATEPANEL,
        payload: {
          name,
          preferredWidth,
          minWidth,
        },
      });
    }, [dispatch, name, preferredWidth, minWidth]);

    return (
      <div
        style={{
          position: 'relative',
          overflowX: 'hidden',
          overflowY: 'auto',
          gridArea: name,
          ...consumerStyle,
        }}
        data-testid={dataTestId}
        className={consumerClassName}
        {...remainingProps}
      >
        <StyledPanel
          data-testid={`page-panel-${name}`}
          ref={rootRef}
          {...(!(prefersReducedMotion || disableAnimations) && animationProps)}
          tabIndex={0}
        >
          {children}
        </StyledPanel>
      </div>
    );
  },
);
